8	import {NodePath} from '@babel/core';
9	import * as t from '@babel/types';
10	import {
11	  CompilerError,
12	  CompilerErrorDetail,
13	  ErrorCategory,
14	} from '../CompilerError';
15	import {ExternalFunction, ReactFunctionType} from '../HIR/Environment';
16	import {CodegenFunction} from '../ReactiveScopes';
17	import {isComponentDeclaration} from '../Utils/ComponentDeclaration';
18	import {isHookDeclaration} from '../Utils/HookDeclaration';
19	import {assertExhaustive} from '../Utils/utils';
20	import {insertGatedFunctionDeclaration} from './Gating';
21	import {
22	  addImportsToProgram,
23	  ProgramContext,
24	  validateRestrictedImports,
25	} from './Imports';
26	import {
27	  CompilerOutputMode,
28	  CompilerReactTarget,
29	  ParsedPluginOptions,
30	  PluginOptions,
31	} from './Options';
32	import {compileFn} from './Pipeline';
33	import {
34	  filterSuppressionsThatAffectFunction,
35	  findProgramSuppressions,
36	  suppressionsToCompilerError,
37	} from './Suppression';
38	import {GeneratedSource} from '../HIR';
39	import {Err, Ok, Result} from '../Utils/Result';
40	
41	export type CompilerPass = {
42	  opts: ParsedPluginOptions;
43	  filename: string | null;
44	  comments: Array<t.CommentBlock | t.CommentLine>;
45	  code: string | null;
46	};
47	export const OPT_IN_DIRECTIVES = new Set(['use forget', 'use memo']);
48	export const OPT_OUT_DIRECTIVES = new Set(['use no forget', 'use no memo']);
49	const DYNAMIC_GATING_DIRECTIVE = new RegExp('^use memo if\\(([^\\)]*)\\)$');
50	
51	export function tryFindDirectiveEnablingMemoization(
52	  directives: Array<t.Directive>,
53	  opts: ParsedPluginOptions,
54	): Result<t.Directive | null, CompilerError> {
55	  const optIn = directives.find(directive =>
56	    OPT_IN_DIRECTIVES.has(directive.value.value),
57	  );
58	  if (optIn != null) {
59	    return Ok(optIn);
60	  }
61	  const dynamicGating = findDirectivesDynamicGating(directives, opts);
62	  if (dynamicGating.isOk()) {
63	    return Ok(dynamicGating.unwrap()?.directive ?? null);
64	  } else {
65	    return Err(dynamicGating.unwrapErr());
66	  }
67	}
68	
69	export function findDirectiveDisablingMemoization(
70	  directives: Array<t.Directive>,
71	  {customOptOutDirectives}: PluginOptions,
72	): t.Directive | null {
73	  if (customOptOutDirectives != null) {
74	    return (
75	      directives.find(
76	        directive =>
77	          customOptOutDirectives.indexOf(directive.value.value) !== -1,
78	      ) ?? null
79	    );
80	  }
81	  return (
82	    directives.find(directive =>
83	      OPT_OUT_DIRECTIVES.has(directive.value.value),
84	    ) ?? null
85	  );
86	}
87	function findDirectivesDynamicGating(
88	  directives: Array<t.Directive>,
89	  opts: ParsedPluginOptions,
90	): Result<
91	  {
92	    gating: ExternalFunction;
93	    directive: t.Directive;
94	  } | null,
95	  CompilerError
96	> {
97	  if (opts.dynamicGating === null) {
98	    return Ok(null);
99	  }
100	  const errors = new CompilerError();
101	  const result: Array<{directive: t.Directive; match: string}> = [];
102	
103	  for (const directive of directives) {
104	    const maybeMatch = DYNAMIC_GATING_DIRECTIVE.exec(directive.value.value);
105	    if (maybeMatch != null && maybeMatch[1] != null) {
106	      if (t.isValidIdentifier(maybeMatch[1])) {
107	        result.push({directive, match: maybeMatch[1]});
108	      } else {
109	        errors.push({
110	          reason: `Dynamic gating directive is not a valid JavaScript identifier`,
111	          description: `Found '${directive.value.value}'`,
112	          category: ErrorCategory.Gating,
113	          loc: directive.loc ?? null,
114	          suggestions: null,
115	        });
116	      }
117	    }
118	  }
119	  if (errors.hasAnyErrors()) {
120	    return Err(errors);
121	  } else if (result.length > 1) {
122	    const error = new CompilerError();
123	    error.push({
124	      reason: `Multiple dynamic gating directives found`,
125	      description: `Expected a single directive but found [${result
126	        .map(r => r.directive.value.value)
127	        .join(', ')}]`,
128	      category: ErrorCategory.Gating,
129	      loc: result[0].directive.loc ?? null,
130	      suggestions: null,
131	    });
132	    return Err(error);
133	  } else if (result.length === 1) {
134	    return Ok({
135	      gating: {
136	        source: opts.dynamicGating.source,
137	        importSpecifierName: result[0].match,
138	      },
139	      directive: result[0].directive,
140	    });
141	  } else {
142	    return Ok(null);
143	  }
144	}
145	
146	function isError(err: unknown): boolean {
147	  return !(err instanceof CompilerError) || err.hasErrors();
148	}
149	
150	function isConfigError(err: unknown): boolean {
151	  if (err instanceof CompilerError) {
152	    return err.details.some(detail => detail.category === ErrorCategory.Config);
153	  }
154	  return false;
155	}
156	
157	export type BabelFn =
158	  | NodePath<t.FunctionDeclaration>
159	  | NodePath<t.FunctionExpression>
160	  | NodePath<t.ArrowFunctionExpression>;
161	
162	export type CompileResult = {
163	  /**
164	   * Distinguishes existing functions that were compiled ('original') from
165	   * functions which were outlined. Only original functions need to be gated
166	   * if gating mode is enabled.
167	   */
168	  kind: 'original' | 'outlined';
169	  originalFn: BabelFn;
170	  compiledFn: CodegenFunction;
171	};
172	
173	function logError(
174	  err: unknown,
175	  context: {
176	    opts: PluginOptions;
177	    filename: string | null;
178	  },
179	  fnLoc: t.SourceLocation | null,
180	): void {
181	  if (context.opts.logger) {
182	    if (err instanceof CompilerError) {
183	      for (const detail of err.details) {
184	        context.opts.logger.logEvent(context.filename, {
185	          kind: 'CompileError',
186	          fnLoc,
187	          detail,
188	        });
189	      }
190	    } else {
191	      let stringifiedError;
192	      if (err instanceof Error) {
193	        stringifiedError = err.stack ?? err.message;
194	      } else {
195	        stringifiedError = err?.toString() ?? '[ null ]';
196	      }
197	
198	      context.opts.logger.logEvent(context.filename, {
199	        kind: 'PipelineError',
200	        fnLoc,
201	        data: stringifiedError,
202	      });
203	    }
204	  }
205	}
206	function handleError(
207	  err: unknown,
208	  context: {
209	    opts: PluginOptions;
210	    filename: string | null;
211	  },
212	  fnLoc: t.SourceLocation | null,
213	): void {
214	  logError(err, context, fnLoc);
215	  if (
216	    context.opts.panicThreshold === 'all_errors' ||
217	    (context.opts.panicThreshold === 'critical_errors' && isError(err)) ||
218	    isConfigError(err) // Always throws regardless of panic threshold
219	  ) {
220	    throw err;
221	  }
222	}
223	
224	export function createNewFunctionNode(
225	  originalFn: BabelFn,
226	  compiledFn: CodegenFunction,
227	): t.FunctionDeclaration | t.ArrowFunctionExpression | t.FunctionExpression {
228	  let transformedFn:
229	    | t.FunctionDeclaration
230	    | t.ArrowFunctionExpression
231	    | t.FunctionExpression;
232	  switch (originalFn.node.type) {
233	    case 'FunctionDeclaration': {
234	      const fn: t.FunctionDeclaration = {
235	        type: 'FunctionDeclaration',
236	        id: compiledFn.id,
237	        loc: originalFn.node.loc ?? null,
238	        async: compiledFn.async,
239	        generator: compiledFn.generator,
240	        params: compiledFn.params,
241	        body: compiledFn.body,
242	      };
243	      transformedFn = fn;
244	      break;
245	    }
246	    case 'ArrowFunctionExpression': {
247	      const fn: t.ArrowFunctionExpression = {
248	        type: 'ArrowFunctionExpression',
249	        loc: originalFn.node.loc ?? null,
250	        async: compiledFn.async,
251	        generator: compiledFn.generator,
252	        params: compiledFn.params,
253	        expression: originalFn.node.expression,
254	        body: compiledFn.body,
255	      };
256	      transformedFn = fn;
257	      break;
258	    }
259	    case 'FunctionExpression': {
260	      const fn: t.FunctionExpression = {
261	        type: 'FunctionExpression',
262	        id: compiledFn.id,
263	        loc: originalFn.node.loc ?? null,
264	        async: compiledFn.async,
265	        generator: compiledFn.generator,
266	        params: compiledFn.params,
267	        body: compiledFn.body,
268	      };
269	      transformedFn = fn;
270	      break;
271	    }
272	    default: {
273	      assertExhaustive(
274	        originalFn.node,
275	        `Creating unhandled function: ${originalFn.node}`,
276	      );
277	    }
278	  }
279	  // Avoid visiting the new transformed version
280	  return transformedFn;
281	}
282	
283	function insertNewOutlinedFunctionNode(
284	  program: NodePath<t.Program>,
285	  originalFn: BabelFn,
286	  compiledFn: CodegenFunction,
287	): BabelFn {
288	  switch (originalFn.type) {
289	    case 'FunctionDeclaration': {
290	      return originalFn.insertAfter(
291	        createNewFunctionNode(originalFn, compiledFn),
292	      )[0]!;
293	    }
294	    /**
295	     * We can't just append the outlined function as a sibling of the original function if it is an
296	     * (Arrow)FunctionExpression parented by a VariableDeclaration, as this would cause its parent
297	     * to become a SequenceExpression instead which breaks a bunch of assumptions elsewhere in the
298	     * plugin.
299	     *
300	     * To get around this, we always synthesize a new FunctionDeclaration for the outlined function
301	     * and insert it as a true sibling to the original function.
302	     */
303	    case 'ArrowFunctionExpression':
304	    case 'FunctionExpression': {
305	      const fn: t.FunctionDeclaration = {
306	        type: 'FunctionDeclaration',
307	        id: compiledFn.id,
308	        loc: originalFn.node.loc ?? null,
309	        async: compiledFn.async,
310	        generator: compiledFn.generator,
311	        params: compiledFn.params,
312	        body: compiledFn.body,
313	      };
314	      const insertedFuncDecl = program.pushContainer('body', [fn])[0]!;
315	      CompilerError.invariant(insertedFuncDecl.isFunctionDeclaration(), {
316	        reason: 'Expected inserted function declaration',
317	        description: `Got: ${insertedFuncDecl}`,
318	        loc: insertedFuncDecl.node?.loc ?? GeneratedSource,
319	      });
320	      return insertedFuncDecl;
321	    }
322	    default: {
323	      assertExhaustive(
324	        originalFn,
325	        `Inserting unhandled function: ${originalFn}`,
326	      );
327	    }
328	  }
329	}
330	
331	const DEFAULT_ESLINT_SUPPRESSIONS = [
332	  'react-hooks/exhaustive-deps',
333	  'react-hooks/rules-of-hooks',
334	];
335	
336	function isFilePartOfSources(
337	  sources: Array<string> | ((filename: string) => boolean),
338	  filename: string,
339	): boolean {
340	  if (typeof sources === 'function') {
341	    return sources(filename);
342	  }
343	
344	  for (const prefix of sources) {
345	    if (filename.indexOf(prefix) !== -1) {
346	      return true;
347	    }
348	  }
349	
350	  return false;
351	}
352	
353	export type CompileProgramMetadata = {
354	  retryErrors: Array<{fn: BabelFn; error: CompilerError}>;
355	};
356	/**
357	 * Main entrypoint for React Compiler.
358	 *
359	 * @param program The Babel program node to compile
360	 * @param pass Compiler configuration and context
361	 * @returns Compilation results or null if compilation was skipped
362	 */
363	export function compileProgram(
364	  program: NodePath<t.Program>,
365	  pass: CompilerPass,
366	): CompileProgramMetadata | null {
367	  /**
368	   * This is directly invoked by the react-compiler babel plugin, so exceptions
369	   * thrown by this function will fail the babel build.
370	   * - call `handleError` if your error is recoverable.
371	   *   Unless the error is a warning / info diagnostic, compilation of a function
372	   *   / entire file should also be skipped.
