1111	}
1112	
1113	function isNonNode(node?: t.Expression | null): boolean {
1114	  if (!node) {
1115	    return true;
1116	  }
1117	  switch (node.type) {
1118	    case 'ObjectExpression':
1119	    case 'ArrowFunctionExpression':
1120	    case 'FunctionExpression':
1121	    case 'BigIntLiteral':
1122	    case 'ClassExpression':
1123	    case 'NewExpression': // technically `new Array()` is legit, but unlikely
1124	      return true;
1125	  }
1126	  return false;
1127	}
1128	
1129	function returnsNonNode(
1130	  node: NodePath<
1131	    t.FunctionDeclaration | t.ArrowFunctionExpression | t.FunctionExpression
1132	  >,
1133	): boolean {
1134	  let returnsNonNode = false;
1135	  if (
1136	    // node.traverse#ArrowFunctionExpression isn't called for the root node
1137	    node.type === 'ArrowFunctionExpression' &&
1138	    node.node.body.type !== 'BlockStatement'
1139	  ) {
1140	    returnsNonNode = isNonNode(node.node.body);
1141	  }
1142	
1143	  node.traverse({
1144	    ReturnStatement(ret) {
1145	      returnsNonNode = isNonNode(ret.node.argument);
1146	    },
1147	    // Skip traversing all nested functions and their return statements
1148	    ArrowFunctionExpression: skipNestedFunctions(node),
1149	    FunctionExpression: skipNestedFunctions(node),
1150	    FunctionDeclaration: skipNestedFunctions(node),
1151	    ObjectMethod: node => node.skip(),
