1268	      const scope = id.scope.getFunctionParent();
1269	      /*
1270	       * A null scope means there's no function scope, which means we're at the
1271	       * top level scope.
1272	       */
1273	      if (scope === null && id.isReferencedIdentifier()) {
1274	        referencedBeforeDeclaration.add(fn.fn);
1275	      }
1276	    },
1277	  });
1278	
1279	  return referencedBeforeDeclaration;
1280	}
